content.content:
1	* { margin: 0; padding: 0; box-sizing: border-box; }
2	
3	:root {
4	  --neon: #3dffc8;
5	  --magenta: #ff3dd1;
6	  --bg: #070a12;
7	  --panel: rgba(10, 14, 24, 0.92);
8	}
9	
10	html, body { height: 100%; overflow: hidden; background: var(--bg); }
11	body { font-family: 'Courier New', Consolas, monospace; color: #cfe7e0; user-select: none; }
12	
13	#stage { position: relative; width: 100vw; height: 100vh; }
14	
15	#view, #overlay {
16	  position: absolute; inset: 0; width: 100%; height: 100%; display: block;
17	}
18	#view { image-rendering: auto; }
19	#overlay { pointer-events: none; }
20	
21	#crosshair {
22	  position: absolute; left: 50%; top: 50%; width: 0; height: 0;
23	  pointer-events: none; z-index: 5;
24	}
25	
26	/* ---------- HUD ---------- */
27	#hud { display: none; position: absolute; inset: 0; pointer-events: none; z-index: 6; }
28	
29	#hud-top {
30	  position: absolute; top: 10px; left: 50%; transform: translateX(-50%);
31	  display: flex; gap: 26px; align-items: baseline;
32	  background: var(--panel); padding: 6px 22px; border: 1px solid rgba(61,255,200,0.25);
33	}
34	#hud-timer { font-size: 22px; color: var(--neon); font-weight: bold; min-width: 70px; text-align: center; }
35	#hud-timer.warn { color: #ff5040; }
36	#hud-score, #hud-round { font-size: 13px; letter-spacing: 1px; opacity: 0.9; }
37	
38	#hud-bottom {
39	  position: absolute; bottom: 14px; left: 0; right: 0;
40	  display: flex; justify-content: space-between; padding: 0 22px;
41	}
42	.hud-block {
43	  background: var(--panel); border: 1px solid rgba(61,255,200,0.25);
44	  padding: 10px 18px; display: flex; gap: 14px; align-items: baseline; font-size: 20px;
45	}
46	.hud-block .hud-label { font-size: 11px; opacity: 0.6; }
47	#hud-hp { color: var(--neon); font-weight: bold; font-size: 26px; }
48	#hud-armor { color: #7fb6ff; }
49	#hud-weapon { font-size: 13px; opacity: 0.85; }
50	#hud-ammo { color: #ffd36b; font-weight: bold; font-size: 24px; }
51	#hud-money { color: #8aff6b; font-size: 16px; }
52	
53	#killfeed {
54	  position: absolute; top: 14px; right: 16px; text-align: right; font-size: 13px;
55	}
56	.feed-entry {
57	  background: rgba(8,10,18,0.75); border-right: 3px solid var(--neon);
58	  padding: 4px 10px; margin-bottom: 4px;
59	}
60	.feed-entry.head { border-right-color: #ff5040; color: #ffb0a6; }
61	
62	#phase-banner {
63	  position: absolute; top: 22%; left: 50%; transform: translateX(-50%);
64	  font-size: 30px; letter-spacing: 6px; color: var(--neon);
65	  text-shadow: 0 0 18px rgba(61,255,200,0.7);
66	  opacity: 0; transition: opacity 0.3s; white-space: nowrap;
67	}
68	#phase-banner.show { opacity: 1; }
69	
70	#fps {
71	  position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%);
72	  font-size: 11px; color: rgba(61,255,200,0.65); z-index: 7; display: none;
73	}
74	
75	/* ---------- buy menu ---------- */
76	#buy-menu {
77	  display: none; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
78	  background: var(--panel); border: 1px solid rgba(61,255,200,0.4);
79	  padding: 22px 26px; pointer-events: auto; min-width: 560px; z-index: 8;
80	}
81	#buy-menu h2 { color: var(--neon); letter-spacing: 3px; font-size: 18px; margin-bottom: 14px; }
82	.buy-hint { font-size: 11px; color: #6b8a83; letter-spacing: 0; margin-left: 10px; }
83	.buy-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
84	.buy-card {
85	  background: rgba(20, 26, 42, 0.9); border: 1px solid rgba(61,255,200,0.2);
86	  color: #cfe7e0; padding: 12px; cursor: pointer; font-family: inherit;
87	  display: flex; flex-direction: column; gap: 5px; text-align: left;
88	}
89	.buy-card:hover { border-color: var(--neon); background: rgba(26, 36, 56, 0.95); }
90	.buy-card.armor { border-color: rgba(127,182,255,0.35); }
91	.buy-name { font-weight: bold; font-size: 13px; }
92	.buy-stats { font-size: 11px; opacity: 0.65; }
93	.buy-price { color: #8aff6b; font-size: 13px; }
94	
95	/* ---------- screens ---------- */
96	.screen {
97	  display: none; position: absolute; inset: 0; z-index: 10;
98	  flex-direction: column; align-items: center; justify-content: center; gap: 16px;
99	  background: radial-gradient(ellipse at center, rgba(7,10,18,0.55) 0%, rgba(7,10,18,0.92) 100%);
100	}
101	.screen h1 {
102	  font-size: 64px; letter-spacing: 14px; color: #e8fff8;
103	  text-shadow: 0 0 30px rgba(61,255,200,0.8);
104	}
105	.screen h1 span { color: var(--neon); }
106	.screen h2 { font-size: 30px; letter-spacing: 8px; color: var(--neon); }
107	.tagline { color: #7da99f; letter-spacing: 2px; font-size: 13px; margin-bottom: 16px; }
108	
109	.btn-primary, .btn-secondary {
110	  font-family: inherit; font-size: 16px; letter-spacing: 4px; cursor: pointer;
111	  padding: 12px 48px; border: 1px solid var(--neon);
112	  background: rgba(61,255,200,0.12); color: var(--neon);
113	  transition: background 0.15s;
114	}
115	.btn-primary:hover { background: rgba(61,255,200,0.3); }
116	.btn-primary.big { font-size: 22px; padding: 16px 70px; }
117	.btn-secondary { border-color: rgba(207,231,224,0.35); background: transparent; color: #cfe7e0; }
118	.btn-secondary:hover { background: rgba(207,231,224,0.1); }
119	
120	.controls-hint {
121	  position: absolute; bottom: 26px; font-size: 11px; color: #5a7d74;
122	  letter-spacing: 1px; max-width: 720px; text-align: center; line-height: 1.7;
123	}
124	
125	#match-result { color: var(--neon); }
126	
127	/* ---------- settings ---------- */
128	#settings-panel {
129	  width: min(680px, 92vw); background: var(--panel);
130	  border: 1px solid rgba(61,255,200,0.3); padding: 18px;
131	  max-height: 78vh; display: flex; flex-direction: column;
132	}
133	.settings-tabs { display: flex; gap: 6px; margin-bottom: 14px; flex-wrap: wrap; }
134	.tab-btn {
135	  font-family: inherit; background: transparent; color: #7da99f;
136	  border: 1px solid rgba(61,255,200,0.2); padding: 7px 16px; cursor: pointer;
137	  letter-spacing: 2px; font-size: 12px;
138	}
139	.tab-btn.active { color: var(--neon); border-color: var(--neon); background: rgba(61,255,200,0.1); }
140	.settings-body { overflow-y: auto; flex: 1; }
141	.settings-row {
142	  display: flex; align-items: center; gap: 12px; padding: 8px 4px;
143	  border-bottom: 1px solid rgba(61,255,200,0.07); font-size: 13px;
144	}
145	.settings-row label { flex: 0 0 240px; color: #a9cdc4; }
146	.settings-row input[type=range] { flex: 1; accent-color: var(--neon); }
147	.settings-row select, .settings-row input[type=color] {
148	  font-family: inherit; background: #0d1322; color: #cfe7e0;
149	  border: 1px solid rgba(61,255,200,0.3); padding: 4px 8px;
150	}
151	.settings-row input[type=checkbox] { width: 18px; height: 18px; accent-color: var(--neon); }
152	.settings-val { min-width: 44px; text-align: right; color: var(--neon); }
153	.settings-footer { display: flex; justify-content: space-between; margin-top: 14px; }
154	.settings-footer button { padding: 9px 26px; font-size: 13px; }
155	
156	.crosshair-preview { padding: 14px 4px; }
157	.ch-preview-stage {
158	  position: relative; height: 90px; background:
159	    linear-gradient(135deg, #1a2438 0%, #2c1a38 100%);
160	  border: 1px solid rgba(61,255,200,0.2);
161	}
162	#ch-preview { position: absolute; left: 50%; top: 50%; }
163	
164	#fatal {
165	  display: none; position: absolute; inset: 0; z-index: 99;
166	  align-items: center; justify-content: center; color: #ff5040;
167	  font-size: 18px; text-align: center; padding: 40px; background: var(--bg);
168	}
