1	// Bootstrap: wires renderer + game + HUD + settings, owns the frame loop,
2	// input handling, screen state, and the headless playtest API (window.GAME).
3	
4	import { Renderer } from './renderer.js';
5	import { Game, WEAPONS } from './game.js';
6	import { AudioEngine } from './audio.js';
7	import { Settings, buildSettingsUI } from './settings.js';
8	import { HUD, buildBuyMenu } from './hud.js';
9	import { MATERIAL_NAMES } from './map.js';
10	
11	const $ = id => document.getElementById(id);
12	
13	const settings = new Settings();
14	const audio = new AudioEngine(settings);
15	const canvas = $('view');
16	
17	let renderer;
18	try {
19	  renderer = new Renderer(canvas);
20	} catch (e) {
21	  $('fatal').textContent = e.message;
22	  $('fatal').style.display = 'flex';
23	  throw e;
24	}
25	
26	let hud;
27	let screen = 'menu'; // menu | game | pause | settings(menuSettings) | buy overlays
28	let buyOpen = false;
29	let pointerLocked = false;
30	let lastT = performance.now();
31	let fpsAcc = 0, fpsN = 0, fpsShown = 0;
32	let frameAccum = 0;
33	
34	const game = new Game(settings, audio, {
35	  onPhase(phase) {
36	    $('phase-banner').textContent = phase === 'buy' ? `ROUND ${game.round} — BUY PHASE` : 'GO GO GO';
37	    $('phase-banner').classList.add('show');
38	    setTimeout(() => $('phase-banner').classList.remove('show'), 1800);
39	    if (phase === 'buy') { buyOpen = true; syncOverlays(); }
40	    if (phase === 'live') { buyOpen = false; syncOverlays(); }
41	  },
42	  onRoundEnd(won, reason) {
43	    $('phase-banner').textContent = `${won ? 'ROUND WON' : 'ROUND LOST'} — ${reason}`;
44	    $('phase-banner').classList.add('show');
45	    setTimeout(() => $('phase-banner').classList.remove('show'), 2600);
46	  },
47	  onMatchEnd(won) {
48	    $('match-result').textContent = won ? 'VICTORY' : 'DEFEAT';
49	    $('match-stats').textContent =
50	      `${game.score.player} : ${game.score.bots} · ${game.kills} kills · ${game.deaths} deaths`;
51	    showScreen('matchend');
52	  },
53	  onKill(bot, head, weapon) {
54	    hud.addKillfeed(`YOU ${head ? '☠' : '⟶'} ${bot.name} [${WEAPONS[weapon].name}]`, head);
55	  },
56	  onDamage() {},
57	  onPlayerDamage(dmg, srcPos) { hud.onPlayerDamage(); },
58	  onShot(info) { hud.onShot(info, currentCam()); },
59	  onBotShot() {},
60	});
61	
62	hud = new HUD(game, settings);
63	
64	// ---------- camera ----------
65	function currentCam() {
66	  const basis = game.player ? game.camBasis() : {
67	    fwd: [Math.sin(menuYaw) * 0.985, -0.17, -Math.cos(menuYaw) * 0.985],
68	    right: [Math.cos(menuYaw), 0, Math.sin(menuYaw)],
69	    up: null,
70	  };
71	  if (!basis.up) {
72	    const f = basis.fwd, r = basis.right;
73	    basis.up = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
74	  }
75	  const gfx = settings.gfx();
76	  let fov = gfx.fov;
77	  if (game.player && game.player.scoped) fov *= 0.28;
78	  return {
79	    pos: game.player ? game.eyePos() : [Math.sin(menuYaw * 0.3) * 6, 9, 24],
80	    fwd: basis.fwd,
81	    right: basis.right,
82	    up: basis.up,
83	    fov,
84	  };
85	}
86	
87	let menuYaw = 0;
88	
89	// ---------- screens ----------
90	function showScreen(s) {
91	  screen = s;
92	  $('menu').style.display = s === 'menu' ? 'flex' : 'none';
93	  $('pause').style.display = s === 'pause' ? 'flex' : 'none';
94	  $('settings-screen').style.display = s === 'settings' ? 'flex' : 'none';
95	  $('matchend').style.display = s === 'matchend' ? 'flex' : 'none';
96	  $('hud').style.display = (s === 'game') ? 'block' : 'none';
97	  syncOverlays();
98	}
99	
100	function syncOverlays() {
101	  $('buy-menu').style.display = (screen === 'game' && buyOpen) ? 'block' : 'none';
102	}
103	
104	let settingsReturnTo = 'menu';
105	function openSettings(from) {
106	  settingsReturnTo = from;
107	  buildSettingsUI($('settings-panel'), settings, () => showScreen(settingsReturnTo));
108	  showScreen('settings');
109	}
110	
111	function startGame() {
112	  audio.unlock();
113	  audio.startAmbient();
114	  game.startMatch();
115	  showScreen('game');
116	  requestPointerLock();
117	}
118	
119	function requestPointerLock() {
120	  if (canvas.requestPointerLock) {
121	    const r = canvas.requestPointerLock();
122	    if (r && r.catch) r.catch(() => {}); // headless or denied: keyboard still works
123	  }
124	}
125	
126	// ---------- input ----------
127	const KEYMAP = { KeyW: 'fwd+', KeyS: 'fwd-', KeyA: 'strafe-', KeyD: 'strafe+' };
128	
129	document.addEventListener('keydown', e => {
130	  if (e.repeat) return;
131	  if (screen === 'game') {
132	    if (KEYMAP[e.code]) applyMove(e.code, true);
133	    else if (e.code === 'Space') game.input.jump = true;
134	    else if (e.code === 'ControlLeft') {
135	      game.input.crouch = settings.get('controls.crouchToggle') ? !game.input.crouch : true;
136	    }
137	    else if (e.code === 'ShiftLeft') game.input.walk = true;
138	    else if (e.code === 'KeyR') game.reload();
139	    else if (e.code === 'KeyB') { buyOpen = !buyOpen; syncOverlays(); }
140	    else if (e.code === 'Digit1') game.switchWeapon(0);
141	    else if (e.code === 'Digit2') game.switchWeapon(1);
142	    else if (e.code === 'Digit3') game.switchWeapon(2);
143	    else if (e.code === 'Escape') { showScreen('pause'); document.exitPointerLock?.(); }
144	  } else if (screen === 'pause' && e.code === 'Escape') {
145	    showScreen('game');
146	    requestPointerLock();
147	  }
148	});
149	
150	document.addEventListener('keyup', e => {
151	  if (KEYMAP[e.code]) applyMove(e.code, false);
152	  else if (e.code === 'Space') game.input.jump = false;
153	  else if (e.code === 'ControlLeft' && !settings.get('controls.crouchToggle')) game.input.crouch = false;
154	  else if (e.code === 'ShiftLeft') game.input.walk = false;
155	});
156	
157	function applyMove(code, down) {
158	  const m = KEYMAP[code];
159	  const axis = m.slice(0, -1);
160	  const dir = m.endsWith('+') ? 1 : -1;
161	  const cur = game.input[axis];
162	  if (down) game.input[axis] = dir;
163	  else if (cur === dir) game.input[axis] = 0;
164	}
165	
166	canvas.addEventListener('mousedown', e => {
167	  if (screen !== 'game') return;
168	  if (!pointerLocked) requestPointerLock();
169	  if (e.button === 0) game.input.fire = true;
170	  if (e.button === 2) game.input.scope = !game.input.scope;
171	});
172	document.addEventListener('mouseup', e => {
173	  if (e.button === 0) game.input.fire = false;
174	});
175	canvas.addEventListener('contextmenu', e => e.preventDefault());
176	
177	document.addEventListener('pointerlockchange', () => {
178	  pointerLocked = document.pointerLockElement === canvas;
179	  if (!pointerLocked && screen === 'game') showScreen('pause');
180	});
181	
182	document.addEventListener('mousemove', e => {
183	  if (!pointerLocked || screen !== 'game' || !game.player) return;
184	  const sens = settings.get('controls.sensitivity') * 0.0022 *
185	    (game.player.scoped ? settings.get('controls.adsScale') : 1);
186	  const inv = settings.get('controls.invertY') ? -1 : 1;
187	  game.player.yaw += e.movementX * sens;
188	  game.player.pitch -= e.movementY * sens * inv;
189	  game.player.pitch = Math.max(-1.55, Math.min(1.55, game.player.pitch));
190	});
191	
192	// menu buttons
193	$('btn-play').addEventListener('click', startGame);
194	$('btn-settings').addEventListener('click', () => openSettings('menu'));
195	$('btn-resume').addEventListener('click', () => { showScreen('game'); requestPointerLock(); });
196	$('btn-pause-settings').addEventListener('click', () => openSettings('pause'));
197	$('btn-quit').addEventListener('click', () => { game.state = 'menu'; showScreen('menu'); });
198	$('btn-again').addEventListener('click', startGame);
199	$('btn-menu').addEventListener('click', () => { game.state = 'menu'; showScreen('menu'); });
200	
201	buildBuyMenu($('buy-menu'), game, item => game.buy(item));
202	
203	settings.onChange(path => {
204	  audio.updateAmbient();
205	  if (path.startsWith('crosshair') || path === '*') hud.updateCrosshair();
206	});
207	
208	// ---------- frame loop ----------
209	function frame(now) {
210	  const dtRaw = (now - lastT) / 1000;
211	  lastT = now;
212	  const dt = Math.min(dtRaw, 0.1);
213	
214	  const gfx = settings.gfx();
215	  if (gfx.frameCap > 0) {
216	    frameAccum += dtRaw;
217	    if (frameAccum < 1 / gfx.frameCap) {
218	      requestAnimationFrame(frame);
219	      return;
220	    }
221	    frameAccum = 0;
222	  }
223	
224	  if (screen === 'menu' || screen === 'matchend') menuYaw += dt * 0.1;
225	  if (screen === 'game') game.update(dt);
226	
227	  renderer.resize(gfx.resolutionScale);
228	  renderer.setSpheres(game.player ? game.renderSpheres() : []);
229	  // muzzle flash light follows the player's gun
230	  if (game.player && hud.flashT > 0) {
231	    const eye = game.eyePos();
232	    const { fwd } = game.camBasis();
233	    renderer.setMuzzleLight(eye[0] + fwd[0] * 1.4, eye[1] + fwd[1] * 1.4 - 0.2, eye[2] + fwd[2] * 1.4, 18, [1, 0.75, 0.4]);
234	  } else {
235	    renderer.setMuzzleLight(0, -100, 0, 0);
236	  }
237	  renderer.render(currentCam(), now / 1000, gfx);
238	
239	  if (screen === 'game') {
240	    hud.draw(dt, currentCam());
241	    hud.updateDOM();
242	    hud.updateCrosshair();
243	  }
244	
245	  // fps counter
246	  fpsAcc += dtRaw; fpsN++;
247	  if (fpsAcc >= 0.5) {
248	    fpsShown = Math.round(fpsN / fpsAcc);
249	    fpsAcc = 0; fpsN = 0;
250	    const el = $('fps');
251	    el.style.display = gfx.showFps ? 'block' : 'none';
252	    el.textContent = `${fpsShown} FPS · RT ${canvas.width}×${canvas.height}`;
253	  }
254	
255	  requestAnimationFrame(frame);
256	}
257	
258	hud.updateCrosshair();
259	showScreen('menu');
260	requestAnimationFrame(frame);
261	
262	// ---------- playtest API ----------
263	window.GAME = {
264	  ready: true,
265	  game, settings, audio, renderer,
266	  materialNames: MATERIAL_NAMES,
267	  test: {
268	    start() { startGame(); },
269	    skipBuy() { if (game.state === 'buy') game.goLive(); },
270	    state() {
271	      return {
272	        screen, gameState: game.state, round: game.round, money: game.money,
273	        kills: game.kills, score: { ...game.score },
274	        hp: game.player ? game.player.hp : null,
275	        pos: game.player ? [...game.player.pos] : null,
276	        botsAlive: game.bots.filter(b => b.alive).length,
277	        fps: fpsShown,
278	        canvas: { w: canvas.width, h: canvas.height },
279	        weapon: game.player ? game.player.current : null,
280	        ammo: game.player ? game.player.weapons[game.player.current].ammo : null,
281	      };
282	    },
283	    pose(x, y, z, yaw, pitch) {
284	      game.player.pos = [x, y, z];
285	      game.player.vel = [0, 0, 0];
286	      game.player.yaw = yaw;
287	      game.player.pitch = pitch;
288	    },
289	    aimAtBot(i) {
290	      const b = game.bots[i];
291	      const eye = game.eyePos();
292	      const h = b.headPos();
293	      const d = [h[0] - eye[0], h[1] - eye[1], h[2] - eye[2]];
294	      game.player.yaw = Math.atan2(d[0], -d[2]);
295	      game.player.pitch = Math.atan2(d[1], Math.hypot(d[0], d[2]));
296	    },
297	    fire() { game.tryFire(); },
298	    damageBot(i, dmg, head = false) { game.damageBot(game.bots[i], dmg, head, 'rifle'); },
299	    buy(item) { return game.buy(item); },
300	    setSetting(path, val) { settings.set(path, val); },
301	    getSetting(path) { return settings.get(path); },
302	    sfxReport() { return audio.report(); },
303	    materialView(id) { renderer.debugMat = id; },
304	    botInfo() {
305	      return game.bots.map(b => ({
306	        name: b.name, alive: b.alive, hp: b.hp, state: b.state,
307	        pos: [+b.pos[0].toFixed(1), +b.pos[1].toFixed(1), +b.pos[2].toFixed(1)],
308	      }));
309	    },
310	    step(dt) { game.update(dt); },
311	  },
312	};
