1	// HUD: DOM for stats/feeds/menus, a 2D overlay canvas for viewmodel weapon,
2	// muzzle flash, tracers, and radar.
3	
4	import { WEAPONS, ARMOR_PRICE } from './game.js';
5	import { BOXES, MAT } from './map.js';
6	import { crosshairCSS, renderCrosshair } from './settings.js';
7	
8	export class HUD {
9	  constructor(game, settings) {
10	    this.game = game;
11	    this.settings = settings;
12	    this.canvas = document.getElementById('overlay');
13	    this.ctx = this.canvas.getContext('2d');
14	    this.crosshairEl = document.getElementById('crosshair');
15	    this.tracers = [];   // {x1,y1,x2,y2,t}
16	    this.flashT = 0;
17	    this.dmgNumbers = []; // {x,y,t,text,head}
18	    this.hitmarkerT = 0;
19	    this.hitmarkerHead = false;
20	    this.vignetteT = 0;
21	    this.killfeed = [];
22	    this.lastWeapon = null;
23	    this.weaponSwitchT = 0;
24	  }
25	
26	  resize() {
27	    const c = this.canvas;
28	    if (c.width !== c.clientWidth || c.height !== c.clientHeight) {
29	      c.width = c.clientWidth;
30	      c.height = c.clientHeight;
31	    }
32	  }
33	
34	  worldToScreen(p, cam) {
35	    const rel = [p[0] - cam.pos[0], p[1] - cam.pos[1], p[2] - cam.pos[2]];
36	    const dz = rel[0] * cam.fwd[0] + rel[1] * cam.fwd[1] + rel[2] * cam.fwd[2];
37	    if (dz < 0.05) return null;
38	    const dx = rel[0] * cam.right[0] + rel[1] * cam.right[1] + rel[2] * cam.right[2];
39	    const dy = rel[0] * cam.up[0] + rel[1] * cam.up[1] + rel[2] * cam.up[2];
40	    const tanY = Math.tan(cam.fov / 2);
41	    const aspect = this.canvas.width / this.canvas.height;
42	    const ndcx = dx / (dz * tanY * aspect);
43	    const ndcy = dy / (dz * tanY);
44	    return [
45	      (ndcx * 0.5 + 0.5) * this.canvas.width,
46	      (1 - (ndcy * 0.5 + 0.5)) * this.canvas.height,
47	    ];
48	  }
49	
50	  onShot(info, cam) {
51	    this.flashT = 0.07;
52	    const def = WEAPONS[info.weapon];
53	    if (!def.melee) {
54	      const mx = this.canvas.width * 0.62;
55	      const my = this.canvas.height * 0.78;
56	      for (const h of info.hits) {
57	        const s = this.worldToScreen(h.point, cam);
58	        if (s) this.tracers.push({ x1: mx, y1: my, x2: s[0], y2: s[1], t: 0.08 });
59	        if (h.bot && this.settings.get('game.damageNumbers')) {
60	          const bs = this.worldToScreen([h.point[0], h.point[1] + 0.5, h.point[2]], cam);
61	          if (bs) this.dmgNumbers.push({ x: bs[0], y: bs[1], t: 0.9, text: `${h.dmg}`, head: h.head });
62	        }
63	      }
64	    }
65	    if (info.hit) {
66	      this.hitmarkerT = 0.18;
67	      this.hitmarkerHead = info.headshot;
68	    }
69	  }
70	
71	  onPlayerDamage() { this.vignetteT = 0.45; }
72	
73	  addKillfeed(text, head) {
74	    if (!this.settings.get('game.killFeed')) return;
75	    this.killfeed.push({ text, head, t: 5 });
76	    if (this.killfeed.length > 5) this.killfeed.shift();
77	  }
78	
79	  updateCrosshair() {
80	    const g = this.game;
81	    const spreadPx = Math.round((g.spread + (g.player ? Math.hypot(g.player.vel[0], g.player.vel[2]) * 0.002 : 0)) * 900);
82	    renderCrosshair(this.crosshairEl, crosshairCSS(this.settings, spreadPx));
83	    this.crosshairEl.style.display = (g.player && g.player.scoped) ? 'none' : 'block';
84	  }
85	
86	  draw(dt, cam) {
87	    this.resize();
88	    const ctx = this.ctx;
89	    const W = this.canvas.width, H = this.canvas.height;
90	    ctx.clearRect(0, 0, W, H);
91	    const g = this.game;
92	    if (!g.player) return;
93	
94	    // tracers
95	    this.tracers = this.tracers.filter(t => (t.t -= dt) > 0);
96	    for (const t of this.tracers) {
97	      ctx.strokeStyle = `rgba(255, 240, 160, ${t.t / 0.08 * 0.85})`;
98	      ctx.lineWidth = 1.5;
99	      ctx.beginPath();
100	      ctx.moveTo(t.x1, t.y1);
101	      ctx.lineTo(t.x2, t.y2);
102	      ctx.stroke();
103	    }
104	
105	    // damage numbers
106	    this.dmgNumbers = this.dmgNumbers.filter(d => (d.t -= dt) > 0);
107	    ctx.textAlign = 'center';
108	    for (const d of this.dmgNumbers) {
109	      const k = 1 - d.t / 0.9;
110	      ctx.font = `bold ${d.head ? 19 : 15}px 'Courier New', monospace`;
111	      ctx.fillStyle = d.head ? `rgba(255,80,60,${d.t})` : `rgba(255,220,120,${d.t})`;
112	      ctx.fillText(d.text, d.x, d.y - k * 36);
113	    }
114	
115	    // hitmarker
116	    if (this.hitmarkerT > 0) {
117	      this.hitmarkerT -= dt;
118	      const a = Math.max(0, this.hitmarkerT / 0.18);
119	      ctx.strokeStyle = this.hitmarkerHead ? `rgba(255,60,40,${a})` : `rgba(255,255,255,${a})`;
120	      ctx.lineWidth = 2;
121	      const cx = W / 2, cy = H / 2, o = 7, l = 7;
122	      ctx.beginPath();
123	      for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
124	        ctx.moveTo(cx + sx * o, cy + sy * o);
125	        ctx.lineTo(cx + sx * (o + l), cy + sy * (o + l));
126	      }
127	      ctx.stroke();
128	    }
129	
130	    // viewmodel + muzzle flash
131	    if (this.settings.get('game.viewmodel') && !g.player.scoped) {
132	      this.drawViewmodel(ctx, W, H, dt);
133	    }
134	
135	    // scope overlay
136	    if (g.player.scoped) {
137	      ctx.fillStyle = 'rgba(0,0,0,0.92)';
138	      const r = Math.min(W, H) * 0.42;
139	      ctx.beginPath();
140	      ctx.rect(0, 0, W, H);
141	      ctx.arc(W / 2, H / 2, r, 0, Math.PI * 2, true);
142	      ctx.fill();
143	      ctx.strokeStyle = 'rgba(120,255,210,0.7)';
144	      ctx.lineWidth = 1;
145	      ctx.beginPath();
146	      ctx.moveTo(W / 2 - r, H / 2); ctx.lineTo(W / 2 + r, H / 2);
147	      ctx.moveTo(W / 2, H / 2 - r); ctx.lineTo(W / 2, H / 2 + r);
148	      ctx.stroke();
149	    }
150	
151	    // radar
152	    if (this.settings.get('game.radar')) this.drawRadar(ctx);
153	
154	    // damage vignette
155	    if (this.vignetteT > 0) {
156	      this.vignetteT -= dt;
157	      const a = this.vignetteT / 0.45 * 0.45;
158	      const grad = ctx.createRadialGradient(W / 2, H / 2, H * 0.3, W / 2, H / 2, H * 0.75);
159	      grad.addColorStop(0, 'rgba(180,0,0,0)');
160	      grad.addColorStop(1, `rgba(180,0,0,${a})`);
161	      ctx.fillStyle = grad;
162	      ctx.fillRect(0, 0, W, H);
163	    }
164	
165	    // low hp pulse
166	    if (g.player.hp <= 30 && g.player.hp > 0) {
167	      const a = 0.12 + 0.08 * Math.sin(g.time * 6);
168	      const grad = ctx.createRadialGradient(W / 2, H / 2, H * 0.35, W / 2, H / 2, H * 0.8);
169	      grad.addColorStop(0, 'rgba(160,0,0,0)');
170	      grad.addColorStop(1, `rgba(160,0,0,${a})`);
171	      ctx.fillStyle = grad;
172	      ctx.fillRect(0, 0, W, H);
173	    }
174	  }
175	
176	  drawViewmodel(ctx, W, H, dt) {
177	    const g = this.game;
178	    const p = g.player;
179	    const def = WEAPONS[p.current];
180	    if (p.current !== this.lastWeapon) { this.lastWeapon = p.current; this.weaponSwitchT = 0.25; }
181	    if (this.weaponSwitchT > 0) this.weaponSwitchT -= dt;
182	
183	    const bob = this.settings.get('controls.viewBobbing')
184	      ? Math.sin(p.bobT * 9) * 6 * Math.min(1, Math.hypot(p.vel[0], p.vel[2]) / 6.4)
185	      : 0;
186	    const kick = g.recoil * 14;
187	    const raise = this.weaponSwitchT > 0 ? this.weaponSwitchT * 240 : 0;
188	    const reloadDip = p.reloadT > 0 ? Math.sin(Math.min(1, 1 - p.reloadT / (def.reloadTime || 1)) * Math.PI) * 60 : 0;
189	
190	    const bx = W * 0.62 + Math.cos(p.bobT * 4.5) * 4;
191	    const by = H * 0.8 + bob + kick + raise + reloadDip;
192	
193	    ctx.save();
194	    ctx.translate(bx, by);
195	    ctx.rotate(-0.06 + g.recoil * -0.05);
196	
197	    // gun silhouette: barrel, body, grip — proportions vary per weapon
198	    const L = def.melee ? 60 : (def.scoped ? 170 : def.slot === 0 ? 130 : 85);
199	    const bodyH = def.melee ? 10 : 26;
200	    ctx.fillStyle = '#15181f';
201	    ctx.strokeStyle = '#2c3340';
202	    ctx.lineWidth = 2;
203	    if (def.melee) {
204	      ctx.save();
205	      ctx.rotate(-0.5);
206	      ctx.fillStyle = '#aeb6c4';
207	      ctx.fillRect(0, -52, 9, 46); // blade
208	      ctx.fillStyle = '#15181f';
209	      ctx.fillRect(-2, -8, 13, 26); // handle
210	      ctx.restore();
211	    } else {
212	      ctx.fillRect(-30, 0, L, bodyH);          // body+barrel
213	      ctx.strokeRect(-30, 0, L, bodyH);
214	      ctx.fillRect(-22, bodyH, 18, 34);         // grip
215	      ctx.fillRect(8, bodyH, 14, 22);           // mag
216	      if (def.scoped) {
217	        ctx.fillRect(10, -14, 52, 12);          // scope
218	        ctx.strokeRect(10, -14, 52, 12);
219	      }
220	      // neon accent
221	      ctx.fillStyle = '#3dffc8';
222	      ctx.fillRect(-30, bodyH - 4, L, 2);
223	    }
224	    ctx.restore();
225	
226	    // muzzle flash
227	    if (this.flashT > 0) {
228	      this.flashT -= dt;
229	      const a = this.flashT / 0.07;
230	      const fx = bx + (def.melee ? 10 : L - 30 + 14);
231	      const fy = by + 8;
232	      const grad = ctx.createRadialGradient(fx, fy, 2, fx, fy, 38);
233	      grad.addColorStop(0, `rgba(255,240,180,${a})`);
234	      grad.addColorStop(0.4, `rgba(255,160,60,${a * 0.7})`);
235	      grad.addColorStop(1, 'rgba(255,120,30,0)');
236	      ctx.fillStyle = grad;
237	      ctx.beginPath();
238	      ctx.arc(fx, fy, 38, 0, Math.PI * 2);
239	      ctx.fill();
240	    }
241	  }
242	
243	  drawRadar(ctx) {
244	    const g = this.game;
245	    const size = 130, pad = 14;
246	    const x0 = pad, y0 = pad;
247	    ctx.save();
248	    ctx.globalAlpha = 0.82;
249	    ctx.fillStyle = 'rgba(8,10,18,0.85)';
250	    ctx.fillRect(x0, y0, size, size);
251	    ctx.strokeStyle = 'rgba(61,255,200,0.5)';
252	    ctx.strokeRect(x0, y0, size, size);
253	
254	    const scale = size / 88; // world is ~84 wide
255	    const toMap = (wx, wz) => [x0 + size / 2 + wx * scale, y0 + size / 2 + wz * scale];
256	
257	    // walls footprint
258	    ctx.fillStyle = 'rgba(61,255,200,0.16)';
259	    for (const b of BOXES) {
260	      if (b[6] === MAT.FLOOR || b[4] < 1.5) continue;
261	      const [mx, my] = toMap(b[0], b[2]);
262	      ctx.fillRect(mx, my, (b[3] - b[0]) * scale, (b[5] - b[2]) * scale);
263	    }
264	    // bots
265	    for (const b of g.bots) {
266	      if (!b.alive) continue;
267	      const [mx, my] = toMap(b.pos[0], b.pos[2]);
268	      ctx.fillStyle = '#ff4040';
269	      ctx.beginPath();
270	      ctx.arc(mx, my, 3, 0, Math.PI * 2);
271	      ctx.fill();
272	    }
273	    // player (with view direction)
274	    const p = g.player;
275	    const [px, py] = toMap(p.pos[0], p.pos[2]);
276	    ctx.fillStyle = '#3dffc8';
277	    ctx.beginPath();
278	    ctx.arc(px, py, 3.5, 0, Math.PI * 2);
279	    ctx.fill();
280	    ctx.strokeStyle = '#3dffc8';
281	    ctx.beginPath();
282	    ctx.moveTo(px, py);
283	    ctx.lineTo(px + Math.sin(p.yaw) * 9, py - Math.cos(p.yaw) * 9);
284	    ctx.stroke();
285	    ctx.restore();
286	  }
