288	  // DOM stats panel
289	  updateDOM() {
290	    const g = this.game;
291	    if (!g.player) return;
292	    setText('hud-hp', Math.max(0, Math.ceil(g.player.hp)));
293	    setText('hud-armor', Math.ceil(g.player.armor));
294	    const def = WEAPONS[g.player.current];
295	    const st = g.player.weapons[g.player.current];
296	    setText('hud-weapon', def.name);
297	    setText('hud-ammo', def.melee ? '—' : `${st.ammo} / ${st.reserve}`);
298	    setText('hud-money', `$${g.money}`);
299	    setText('hud-round', `R${g.round}`);
300	    setText('hud-score', `YOU ${g.score.player} : ${g.score.bots} BOTS`);
301	    const t = Math.max(0, g.phaseT);
302	    const mm = Math.floor(t / 60), ss = Math.floor(t % 60);
303	    setText('hud-timer', g.state === 'buy' ? `BUY ${Math.ceil(t)}` : `${mm}:${String(ss).padStart(2, '0')}`);
304	    document.getElementById('hud-timer').classList.toggle('warn', g.state === 'live' && t < 20);
305	
306	    const feedEl = document.getElementById('killfeed');
307	    this.killfeed = this.killfeed.filter(k => (k.t -= 1 / 60) > 0);
308	    feedEl.innerHTML = this.killfeed
309	      .map(k => `<div class="feed-entry${k.head ? ' head' : ''}">${k.text}</div>`)
310	      .join('');
311	  }
312	}
