76	export class Settings {
77	  constructor() {
78	    this.values = {};
79	    this.listeners = [];
80	    for (const [g, group] of Object.entries(SCHEMA)) {
81	      this.values[g] = {};
82	      for (const [k, item] of Object.entries(group.items)) {
83	        this.values[g][k] = item.default;
84	      }
85	    }
86	    this._load();
87	  }
88	
89	  _load() {
90	    try {
91	      const raw = localStorage.getItem(STORAGE_KEY);
92	      if (!raw) return;
93	      const saved = JSON.parse(raw);
94	      for (const g of Object.keys(this.values)) {
95	        if (!saved[g]) continue;
96	        for (const k of Object.keys(this.values[g])) {
97	          if (k in saved[g]) this.values[g][k] = saved[g][k];
98	        }
99	      }
100	    } catch (e) { /* corrupted save: keep defaults */ }
101	  }
102	
103	  save() {
104	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.values)); } catch (e) { /* private mode */ }
105	  }
106	
107	  get(path) {
108	    const [g, k] = path.split('.');
109	    return this.values[g][k];
110	  }
111	
112	  set(path, val, opts = {}) {
113	    const [g, k] = path.split('.');
114	    const item = SCHEMA[g].items[k];
115	    if (item.type === 'range') {
116	      val = Math.max(item.min, Math.min(item.max, Number(val)));
117	    } else if (item.type === 'bool') {
118	      val = !!val;
119	    }
120	    this.values[g][k] = val;
121	    // applying a preset writes graphics keys; manual graphics edits flip preset to custom
122	    if (g === 'graphics' && k !== 'preset' && k !== 'fov' && k !== 'frameCap' && k !== 'showFps' && !opts.fromPreset) {
123	      this.values.graphics.preset = 'custom';
124	    }
