174	  const groups = Object.keys(SCHEMA);
175	  let active = groups[0];
176	
177	  function renderBody() {
178	    body.innerHTML = '';
179	    const group = SCHEMA[active];
180	    for (const [k, item] of Object.entries(group.items)) {
181	      const row = document.createElement('div');
182	      row.className = 'settings-row';
183	      const label = document.createElement('label');
184	      label.textContent = item.label;
185	      row.appendChild(label);
186	      const path = `${active}.${k}`;
187	      const cur = settings.get(path);
188	
189	      let input;
190	      if (item.type === 'range') {
191	        input = document.createElement('input');
192	        input.type = 'range';
193	        input.min = item.min; input.max = item.max; input.step = item.step;
194	        input.value = cur;
195	        const valSpan = document.createElement('span');
196	        valSpan.className = 'settings-val';
197	        valSpan.textContent = cur;
198	        input.addEventListener('input', () => {
199	          settings.set(path, Number(input.value));
200	          valSpan.textContent = settings.get(path);
201	        });
202	        row.appendChild(input);
203	        row.appendChild(valSpan);
204	      } else if (item.type === 'bool') {
205	        input = document.createElement('input');
206	        input.type = 'checkbox';
207	        input.checked = cur;
208	        input.addEventListener('change', () => settings.set(path, input.checked));
209	        row.appendChild(input);
210	      } else if (item.type === 'enum') {
211	        input = document.createElement('select');
212	        for (const opt of item.options) {
213	          const o = document.createElement('option');
214	          o.value = opt; o.textContent = opt;
215	          if (opt === cur) o.selected = true;
216	          input.appendChild(o);
217	        }
218	        input.addEventListener('change', () => {
219	          settings.set(path, input.value);
220	          if (path === 'graphics.preset') renderBody(); // preset rewrites sliders
221	        });
222	        row.appendChild(input);
223	      } else if (item.type === 'color') {
224	        input = document.createElement('input');
225	        input.type = 'color';
226	        input.value = cur;
227	        input.addEventListener('input', () => settings.set(path, input.value));
228	        row.appendChild(input);
229	      }
230	      input.dataset.setting = path;
231	      body.appendChild(row);
232	    }
233	    if (active === 'crosshair') {
234	      const prev = document.createElement('div');
235	      prev.className = 'crosshair-preview';
236	      prev.innerHTML = '<div class="ch-preview-stage"><div id="ch-preview"></div></div>';
237	      body.appendChild(prev);
238	      drawCrosshairPreview(settings);
239	    }
240	  }
241	
242	  for (const g of groups) {
243	    const btn = document.createElement('button');
244	    btn.className = 'tab-btn';
245	    btn.textContent = SCHEMA[g].label;
246	    btn.dataset.tab = g;
247	    btn.addEventListener('click', () => {
248	      active = g;
249	      tabs.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === g));
250	      renderBody();
251	    });
252	    if (g === active) btn.classList.add('active');
253	    tabs.appendChild(btn);
254	  }
255	
256	  const footer = document.createElement('div');
257	  footer.className = 'settings-footer';
258	  const reset = document.createElement('button');
259	  reset.className = 'btn-secondary';
260	  reset.textContent = 'Reset Defaults';
261	  reset.addEventListener('click', () => { settings.resetDefaults(); renderBody(); });
262	  const close = document.createElement('button');
263	  close.className = 'btn-primary';
264	  close.textContent = 'Done';
265	  close.addEventListener('click', onClose);
266	  footer.appendChild(reset);
267	  footer.appendChild(close);
268	  container.appendChild(footer);
269	
270	  settings.onChange((path) => {
271	    if (path.startsWith('crosshair') || path === '*') drawCrosshairPreview(settings);
272	  });
273	
274	  renderBody();
275	}
