277	export function crosshairCSS(settings, spreadPx = 0) {
278	  const s = {
279	    style: settings.get('crosshair.style'),
280	    size: settings.get('crosshair.size'),
281	    gap: settings.get('crosshair.gap') + (settings.get('crosshair.dynamic') ? spreadPx : 0),
282	    th: settings.get('crosshair.thickness'),
283	    color: settings.get('crosshair.color'),
284	    outline: settings.get('crosshair.outline'),
285	  };
286	  return s;
287	}
288	
289	export function renderCrosshair(el, s) {
290	  el.innerHTML = '';
291	  const mk = (w, h, x, y) => {
292	    const d = document.createElement('div');
293	    d.style.cssText = `position:absolute;background:${s.color};width:${w}px;height:${h}px;` +
294	      `left:${x}px;top:${y}px;${s.outline ? 'box-shadow:0 0 0 1px rgba(0,0,0,0.8);' : ''}`;
295	    el.appendChild(d);
296	  };
297	  const { size, gap, th } = s;
298	  if (s.style === 'cross' || s.style === 'cross+dot') {
299	    mk(size, th, -gap - size, -th / 2);
300	    mk(size, th, gap, -th / 2);
301	    mk(th, size, -th / 2, -gap - size);
302	    mk(th, size, -th / 2, gap);
303	  }
304	  if (s.style === 'dot' || s.style === 'cross+dot') {
305	    mk(th + 1, th + 1, -(th + 1) / 2, -(th + 1) / 2);
306	  }
307	  if (s.style === 'circle') {
308	    const d = document.createElement('div');
309	    d.style.cssText = `position:absolute;border:${th}px solid ${s.color};border-radius:50%;` +
310	      `width:${size * 2}px;height:${size * 2}px;left:${-size - th}px;top:${-size - th}px;` +
311	      (s.outline ? 'box-shadow:0 0 0 1px rgba(0,0,0,0.8), inset 0 0 0 1px rgba(0,0,0,0.8);' : '');
312	    el.appendChild(d);
313	  }
314	}
315	
316	function drawCrosshairPreview(settings) {
317	  const el = document.getElementById('ch-preview');
318	  if (!el) return;
319	  renderCrosshair(el, crosshairCSS(settings));
320	}
