38	// ---------- collision ----------
39	function collideAxis(pos, half, axis, delta) {
40	  pos[axis] += delta;
41	  const min = [pos[0] - half[0], pos[1], pos[2] - half[2]];
42	  const max = [pos[0] + half[0], pos[1] + half[1] * 2, pos[2] + half[2]];
43	  for (const b of SOLIDS) {
44	    if (max[0] <= b[0] || min[0] >= b[3] || max[1] <= b[1] || min[1] >= b[4] || max[2] <= b[2] || min[2] >= b[5]) continue;
45	    if (delta > 0) pos[axis] = (axis === 1 ? b[1] - half[1] * 2 : b[axis] - half[axis === 0 ? 0 : 2]) - 1e-4;
46	    else pos[axis] = (axis === 1 ? b[4] : b[axis + 3] + half[axis === 0 ? 0 : 2]) + 1e-4;
47	    return true;
48	  }
49	  return false;
50	}
51	
52	export function rayWorld(ro, rd, maxT) {
53	  // CPU mirror of the shader's box traversal — used for hitscan and LOS
54	  let best = maxT, hit = false;
55	  for (const b of SOLIDS) {
56	    let tmin = -Infinity, tmax = Infinity;
57	    for (let a = 0; a < 3; a++) {
58	      const inv = 1 / rd[a];
59	      let t0 = (b[a] - ro[a]) * inv;
60	      let t1 = (b[a + 3] - ro[a]) * inv;
61	      if (inv < 0) { const tmp = t0; t0 = t1; t1 = tmp; }
62	      tmin = Math.max(tmin, t0);
63	      tmax = Math.min(tmax, t1);
64	      if (tmin > tmax) break;
65	    }
66	    if (tmin <= tmax && tmax > 0.001) {
67	      const t = tmin > 0.001 ? tmin : tmax;
68	      if (t < best) { best = t; hit = true; }
69	    }
70	  }
71	  return hit ? best : -1;
72	}
73	
74	function raySphere(ro, rd, c, r) {
75	  const oc = [ro[0] - c[0], ro[1] - c[1], ro[2] - c[2]];
76	  const b = oc[0] * rd[0] + oc[1] * rd[1] + oc[2] * rd[2];
77	  const cc = oc[0] ** 2 + oc[1] ** 2 + oc[2] ** 2 - r * r;
78	  const h = b * b - cc;
79	  if (h < 0) return -1;
80	  const t = -b - Math.sqrt(h);
81	  return t > 0 ? t : -1;
82	}
83	
84	// ---------- waypoint graph ----------
85	const ADJ = WAYPOINTS.map(() => []);
86	for (const [a, b] of WAYPOINT_EDGES) { ADJ[a].push(b); ADJ[b].push(a); }
87	
88	function nearestWaypoint(x, z) {
89	  let best = 0, bd = Infinity;
90	  for (let i = 0; i < WAYPOINTS.length; i++) {
91	    const d = (WAYPOINTS[i].x - x) ** 2 + (WAYPOINTS[i].z - z) ** 2;
92	    if (d < bd) { bd = d; best = i; }
93	  }
94	  return best;
95	}
96	
97	function findPath(from, to) {
98	  if (from === to) return [to];
99	  const prev = new Array(WAYPOINTS.length).fill(-1);
100	  const q = [from];
101	  prev[from] = from;
102	  while (q.length) {
103	    const n = q.shift();
104	    if (n === to) break;
105	    for (const m of ADJ[n]) {
106	      if (prev[m] === -1) { prev[m] = n; q.push(m); }
107	    }
108	  }
109	  if (prev[to] === -1) return [to];
110	  const path = [to];
111	  let n = to;
112	  while (n !== from) { n = prev[n]; path.unshift(n); }
113	  return path;
114	}
