198	  startRound() {
199	    this.round++;
200	    this.state = 'buy';
201	    this.phaseT = 6;
202	    const p = this.player;
203	    p.pos = [PLAYER_SPAWN.x, PLAYER_SPAWN.y, PLAYER_SPAWN.z];
