230	  endRound(playerWon, reason) {
231	    if (this.state === 'end' || this.state === 'matchend') return;
232	    this.state = 'end';
233	    this.phaseT = 3.5;
234	    if (playerWon) {
235	      this.score.player++;
236	      this.money = Math.min(16000, this.money + 3250);
237	      this.audio.play('round_win', { category: 'ui' });
238	    } else {
239	      this.score.bots++;
