250	  buy(item) {
251	    if (this.state !== 'buy' && !(this.state === 'live' && this.phaseT > this.settings.get('game.roundTime') - 10)) {
252	      this.audio.play('deny', { category: 'ui' });
253	      return false;
254	    }
255	    if (item === 'armor') {
256	      if (this.money < ARMOR_PRICE || this.player.armor >= 100) {
257	        this.audio.play('deny', { category: 'ui' });
258	        return false;
259	      }
260	      this.money -= ARMOR_PRICE;
261	      this.player.armor = 100;
262	      this.audio.play('buy', { category: 'ui' });
263	      return true;
264	    }
265	    const def = WEAPONS[item];
266	    if (!def || this.money < def.price || this.player.weapons[item]) {
267	      this.audio.play('deny', { category: 'ui' });
268	      return false;
