287	  // ---------- camera helpers ----------
288	  eyeHeight() {
289	    return this.player.crouching ? EYE_CROUCH : EYE_STAND;
290	  }
291	  camBasis() {
292	    const p = this.player;
293	    const cy = Math.cos(p.yaw), sy = Math.sin(p.yaw);
294	    const cp = Math.cos(p.pitch), sp = Math.sin(p.pitch);
295	    const fwd = [sy * cp, sp, -cy * cp];
296	    const right = [cy, 0, sy];
297	    const up = [
298	      right[1] * fwd[2] - right[2] * fwd[1],
299	      right[2] * fwd[0] - right[0] * fwd[2],
300	      right[0] * fwd[1] - right[1] * fwd[0],
301	    ];
302	    return { fwd, right, up };
303	  }
304	  eyePos() {
305	    const p = this.player;
306	    let bob = 0;
307	    if (this.settings.get('controls.viewBobbing')) {
308	      bob = Math.sin(p.bobT * 9) * 0.035 * Math.min(1, Math.hypot(p.vel[0], p.vel[2]) / RUN_SPEED);
309	    }
310	    return [p.pos[0], p.pos[1] + this.eyeHeight() + bob, p.pos[2]];
311	  }
312	
313	  // ---------- firing ----------
314	  tryFire() {
315	    const p = this.player;
316	    if (p.fireCd > 0 || p.reloadT > 0) return;
317	    const def = WEAPONS[p.current];
318	    const st = p.weapons[p.current];
319	    if (!def.melee && st.ammo <= 0) {
320	      this.audio.play('dryfire', { category: 'sfx' });
321	      p.fireCd = 0.3;
322	      return;
323	    }
324	    p.fireCd = 60 / def.rpm;
325	    if (!def.melee) st.ammo--;
326	
327	    const { fwd, right, up } = this.camBasis();
328	    const eye = this.eyePos();
329	    const pellets = def.pellets || 1;
330	    const moveSpread = Math.min(0.03, Math.hypot(p.vel[0], p.vel[2]) * 0.004);
331	    const totalSpread = (p.scoped ? def.spread * 0.2 : def.spread) + this.spread + moveSpread;
332	    let anyHit = false, anyHs = false;
333	    const hits = [];
334	
335	    for (let pi = 0; pi < pellets; pi++) {
336	      const rx = (Math.random() - 0.5) * 2 * totalSpread;
337	      const ry = (Math.random() - 0.5) * 2 * totalSpread;
338	      const rd = norm3([
339	        fwd[0] + right[0] * rx + up[0] * ry,
340	        fwd[1] + right[1] * rx + up[1] * ry,
341	        fwd[2] + right[2] * rx + up[2] * ry,
342	      ]);
343	      const wallT = rayWorld(eye, rd, def.range);
344	      const maxT = wallT > 0 ? wallT : def.range;
345	      let bestBot = null, bestT = maxT, isHead = false;
346	      for (const b of this.bots) {
347	        if (!b.alive) continue;
348	        const th = raySphere(eye, rd, b.headPos(), 0.3);
349	        if (th > 0 && th < bestT) { bestT = th; bestBot = b; isHead = true; }
350	        const tb = raySphere(eye, rd, b.bodyPos(), 0.55);
351	        if (tb > 0 && tb < bestT) { bestT = tb; bestBot = b; isHead = false; }
352	      }
353	      if (bestBot) {
354	        const dmg = Math.round(def.dmg * (isHead ? def.hsMult : 1));
355	        this.damageBot(bestBot, dmg, isHead, p.current);
356	        anyHit = true;
357	        anyHs = anyHs || isHead;
358	        hits.push({ bot: bestBot, dmg, head: isHead, point: addScaled(eye, rd, bestT) });
359	      } else if (wallT > 0) {
360	        hits.push({ point: addScaled(eye, rd, wallT) });
361	      }
362	    }
363	
364	    this.audio.play(def.sfx, { category: 'sfx' });
365	    if (anyHit && this.settings.get('audio.hitsound')) {
366	      this.audio.play(anyHs ? 'headshot' : 'hit', { category: 'ui', vol: 0.8 });
367	    }
368	    // recoil + bloom
369	    if (!def.melee) {
370	      p.pitch = Math.min(Math.PI / 2, p.pitch + (def.dmg / 1400) * (p.scoped ? 0.3 : 1));
371	      p.yaw += (Math.random() - 0.5) * 0.004;
372	      this.spread = Math.min(0.04, this.spread + def.spread * 0.8);
373	      this.recoil = 1;
374	    }
375	    this.events.onShot({ weapon: p.current, hits, headshot: anyHs, hit: anyHit });
376	  }
