378	  damageBot(bot, dmg, isHead, weapon) {
379	    if (!bot.alive) return;
380	    bot.hp -= dmg;
381	    // getting shot alerts the bot
382	    bot.state = 'attack';
383	    bot.seenT = 0.5;
384	    this.events.onDamage(bot, dmg, isHead);
385	    if (bot.hp <= 0) {
386	      bot.alive = false;
387	      bot.deathT = 0.6;
388	      this.kills++;
389	      this.money = Math.min(16000, this.money + 300);
390	      const rel = this.relativeAudio(bot.pos);
391	      this.audio.play('bot_death', { category: 'sfx', pan: rel.pan, dist: rel.dist });
392	      this.events.onKill(bot, isHead, weapon);
393	      if (this.state === 'live' && this.bots.every(b => !b.alive)) {
394	        this.endRound(true, 'All hostiles eliminated');
395	      }
396	    }
397	  }
