399	  reload() {
400	    const p = this.player;
401	    const def = WEAPONS[p.current];
402	    const st = p.weapons[p.current];
403	    if (def.melee || p.reloadT > 0 || st.ammo >= def.mag || st.reserve <= 0) return;
404	    p.reloadT = def.reloadTime;
405	    this.audio.play('reload', { category: 'sfx' });
406	  }
407	
408	  relativeAudio(srcPos) {
409	    const eye = this.eyePos();
410	    const d = [srcPos[0] - eye[0], srcPos[1] - eye[1], srcPos[2] - eye[2]];
411	    const dist = Math.hypot(...d);
412	    const { right } = this.camBasis();
413	    const pan = dist > 0.01 ? (d[0] * right[0] + d[1] * right[1] + d[2] * right[2]) / dist : 0;
414	    return { pan, dist };
415	  }
