417	  damagePlayer(dmg, srcPos) {
418	    const p = this.player;
419	    if (p.armor > 0) {
420	      const absorbed = Math.min(p.armor, dmg * 0.5);
421	      p.armor -= absorbed;
422	      dmg -= absorbed;
423	    }
424	    p.hp -= dmg;
425	    const rel = this.relativeAudio(srcPos);
426	    this.audio.play('hurt', { category: 'sfx', pan: rel.pan, vol: 0.9 });
427	    this.events.onPlayerDamage(dmg, srcPos);
428	    if (p.hp <= 0) {
429	      p.hp = 0;
430	      this.deaths++;
431	      this.endRound(false, 'You were eliminated');
432	    }
433	  }
434	
435	  // ---------- per-frame ----------
436	  update(dt) {
437	    if (this.state === 'menu' || this.state === 'matchend') return;
438	    dt = Math.min(dt, 0.05);
439	    this.time += dt;
440	
441	    if (this.state === 'buy') {
442	      this.phaseT -= dt;
443	      if (this.phaseT <= 0) this.goLive();
444	      this.updateViewmodelTimers(dt);
445	      return; // frozen during buy
446	    }
447	    if (this.state === 'end') {
448	      this.phaseT -= dt;
449	      this.updateBots(dt); // let corpses sink
450	      if (this.phaseT <= 0) this.startRound();
451	      return;
452	    }
453	    // live
454	    this.phaseT -= dt;
455	    if (this.phaseT <= 0) {
456	      this.endRound(false, 'Time expired');
457	      return;
458	    }
459	    this.updatePlayer(dt);
460	    this.updateBots(dt);
461	    this.updateViewmodelTimers(dt);
462	  }
463	
464	  updateViewmodelTimers(dt) {
465	    const p = this.player;
466	    p.fireCd = Math.max(0, p.fireCd - dt);
467	    if (p.reloadT > 0) {
468	      p.reloadT -= dt;
469	      if (p.reloadT <= 0) {
470	        const def = WEAPONS[p.current];
471	        const st = p.weapons[p.current];
472	        const need = def.mag - st.ammo;
473	        const take = Math.min(need, st.reserve);
474	        st.ammo += take;
475	        st.reserve -= take;
476	      }
477	    }
478	    this.spread = Math.max(0, this.spread - dt * 0.06);
479	    this.recoil = Math.max(0, this.recoil - dt * 6);
480	  }
481	
482	  updatePlayer(dt) {
483	    const p = this.player;
484	    const inp = this.input;
485	    p.crouching = inp.crouch;
486	    const speed = p.crouching ? CROUCH_SPEED : (inp.walk ? WALK_SPEED : RUN_SPEED);
487	
488	    const cy = Math.cos(p.yaw), sy = Math.sin(p.yaw);
489	    let mx = (sy * inp.fwd + cy * inp.strafe);
490	    let mz = (-cy * inp.fwd + sy * inp.strafe);
491	    const ml = Math.hypot(mx, mz);
492	    if (ml > 1) { mx /= ml; mz /= ml; }
493	
494	    // accelerate toward wish velocity (snappy, CS-like)
495	    const accel = p.onGround ? 14 : 2.5;
496	    p.vel[0] += (mx * speed - p.vel[0]) * Math.min(1, accel * dt);
497	    p.vel[2] += (mz * speed - p.vel[2]) * Math.min(1, accel * dt);
498	
499	    if (inp.jump && p.onGround) {
500	      p.vel[1] = JUMP_VEL;
501	      p.onGround = false;
502	      this.audio.play('jump', { category: 'sfx', vol: 0.6 });
503	    }
504	    p.vel[1] -= GRAVITY * dt;
505	
506	    const half = [PLAYER_RADIUS, (p.crouching ? 1.3 : PLAYER_HEIGHT) / 2, PLAYER_RADIUS];
507	    collideAxis(p.pos, half, 0, p.vel[0] * dt);
508	    collideAxis(p.pos, half, 2, p.vel[2] * dt);
509	    const wasAir = !p.onGround;
510	    const hitY = collideAxis(p.pos, half, 1, p.vel[1] * dt);
511	    if (hitY) {
512	      if (p.vel[1] < 0) {
513	        p.onGround = true;
514	        if (wasAir && p.vel[1] < -5) this.audio.play('land', { category: 'sfx', vol: 0.6 });
515	      }
516	      p.vel[1] = 0;
517	    } else if (p.pos[1] <= 0 && p.vel[1] <= 0) {
518	      p.pos[1] = 0;
519	      if (wasAir && p.vel[1] < -5) this.audio.play('land', { category: 'sfx', vol: 0.6 });
520	      p.vel[1] = 0;
521	      p.onGround = true;
522	    } else {
523	      p.onGround = false;
524	    }
525	
526	    // footsteps
527	    const hSpeed = Math.hypot(p.vel[0], p.vel[2]);
528	    if (p.onGround && hSpeed > 1.5) {
529	      p.bobT += dt * (hSpeed / RUN_SPEED);
530	      if (!p._stepT) p._stepT = 0;
531	      p._stepT -= dt * (hSpeed / RUN_SPEED);
532	      if (p._stepT <= 0 && !inp.walk && !p.crouching) {
533	        p._stepT = 0.42;
534	        this.audio.play('footstep', { category: 'sfx', vol: 0.7 });
535	      }
536	    }
537	
538	    // firing
539	    if (inp.fire) {
540	      const def = WEAPONS[p.current];
541	      if (def.auto || p._fireLatch !== true) {
542	        this.tryFire();
543	        p._fireLatch = true;
544	      }
545	    } else {
546	      p._fireLatch = false;
547	    }
548	    p.scoped = inp.scope && WEAPONS[p.current].scoped === true;
549	  }
