551	  hasLOS(from, to) {
552	    const d = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
553	    const dist = Math.hypot(...d);
554	    if (dist < 0.01) return true;
555	    const rd = d.map(v => v / dist);
556	    const t = rayWorld(from, rd, dist - 0.05);
557	    return t < 0;
558	  }
559	
560	  updateBots(dt) {
561	    const p = this.player;
562	    const eye = this.eyePos();
563	    for (const b of this.bots) {
564	      if (!b.alive) {
565	        if (b.deathT > 0) b.deathT -= dt;
566	        continue;
567	      }
568	      if (this.state !== 'live') continue;
569	      const head = b.headPos();
570	      const toP = [p.pos[0] - b.pos[0], 0, p.pos[2] - b.pos[2]];
571	      const distP = Math.hypot(toP[0], toP[2]);
572	
573	      // vision: distance + facing cone + LOS
574	      let sees = false;
575	      if (distP < b.diff.viewDist) {
576	        const facing = [Math.sin(b.yaw), 0, -Math.cos(b.yaw)];
577	        const dot = (toP[0] * facing[0] + toP[2] * facing[2]) / (distP || 1);
578	        if (dot > 0.34 || distP < 4) {
579	          sees = this.hasLOS(head, eye);
580	        }
581	      }
582	
583	      if (sees) {
584	        b.seenT += dt;
585	        b.lastKnown = [...p.pos];
586	        if (b.state !== 'attack' && b.seenT >= b.diff.reaction) b.state = 'attack';
587	      } else {
588	        b.seenT = Math.max(0, b.seenT - dt * 0.5);
589	        if (b.state === 'attack' && b.seenT <= 0) {
590	          b.state = 'seek';
591	          b.repathT = 0;
592	        }
593	      }
594	
595	      if (b.state === 'attack' && sees) {
596	        // face player
597	        b.yaw = Math.atan2(toP[0], -toP[2]);
598	        // strafe
599	        b.strafeT -= dt;
600	        if (b.strafeT <= 0) { b.strafeT = 0.5 + Math.random(); b.strafeDir *= -1; }
601	        const sdx = Math.cos(b.yaw) * b.strafeDir, sdz = Math.sin(b.yaw) * b.strafeDir;
602	        this.moveBot(b, sdx * 2.2, sdz * 2.2, dt);
603	        // shoot
604	        b.fireCd -= dt;
605	        if (b.fireCd <= 0) {
606	          b.fireCd = (60 / 400) / b.diff.rpmScale;
607	          const spread = b.diff.spread * (1 + distP * 0.03);
608	          const miss = Math.random() * spread * distP;
609	          const rel = this.relativeAudio(head);
610	          this.audio.play('shot_rifle', { category: 'sfx', pan: rel.pan, dist: rel.dist, vol: 0.8 });
611	          this.events.onBotShot(b);
612	          if (miss < 0.55 && this.hasLOS(head, eye)) {
613	            this.damagePlayer(b.diff.dmg, head);
614	          }
615	        }
616	      } else {
617	        // navigate: patrol or seek last known position
618	        b.repathT -= dt;
619	        if (!b.path.length || b.pathI >= b.path.length || b.repathT <= 0) {
620	          const from = nearestWaypoint(b.pos[0], b.pos[2]);
621	          let targetWp;
622	          if (b.state === 'seek' && b.lastKnown) {
623	            targetWp = nearestWaypoint(b.lastKnown[0], b.lastKnown[2]);
624	            if (from === targetWp) { b.state = 'patrol'; b.lastKnown = null; }
625	          }
626	          if (b.state !== 'seek') {
627	            targetWp = Math.floor(Math.random() * WAYPOINTS.length);
628	          }
629	          b.path = findPath(from, targetWp);
630	          b.pathI = 0;
631	          b.repathT = 6 + Math.random() * 4;
632	        }
633	        const wp = WAYPOINTS[b.path[Math.min(b.pathI, b.path.length - 1)]];
634	        const dx = wp.x - b.pos[0], dz = wp.z - b.pos[2];
635	        const d = Math.hypot(dx, dz);
636	        if (d < 1.2) {
637	          b.pathI++;
638	        } else {
639	          const sp = b.state === 'seek' ? 4.6 : 3.2;
640	          b.yaw = Math.atan2(dx, -dz);
641	          this.moveBot(b, (dx / d) * sp, (dz / d) * sp, dt);
642	        }
643	      }
644	    }
645	  }
646	
647	  moveBot(b, vx, vz, dt) {
648	    const half = [0.4, 0.9, 0.4];
649	    collideAxis(b.pos, half, 0, vx * dt);
650	    collideAxis(b.pos, half, 2, vz * dt);
651	    if (b.pos[1] > 0) b.pos[1] = Math.max(0, b.pos[1] - 8 * dt);
652	  }
653	
654	  // spheres for the ray tracer
655	  renderSpheres() {
656	    const out = [];
657	    for (const b of this.bots) {
658	      if (!b.alive && b.deathT <= 0) continue;
659	      const sink = b.alive ? 0 : (1 - b.deathT / 0.6) * 1.6;
660	      out.push({ x: b.pos[0], y: b.pos[1] + 0.9 - sink, z: b.pos[2], r: 0.55, mat: MAT.BOT_BODY });
661	      out.push({ x: b.pos[0], y: b.pos[1] + 1.55 - sink, z: b.pos[2], r: 0.3, mat: MAT.BOT_HEAD });
662	    }
663	    return out;
664	  }
665	}
