667	function norm3(v) {
668	  const l = Math.hypot(...v) || 1;
669	  return [v[0] / l, v[1] / l, v[2] / l];
670	}
671	function addScaled(a, d, t) {
672	  return [a[0] + d[0] * t, a[1] + d[1] * t, a[2] + d[2] * t];
673	}
