1	// Procedural SFX. Every sound is synthesized into a Float32Array by pure DSP
2	// (no AudioContext needed for generation), so the playtest harness can verify
3	// peak/RMS/duration of every effect headlessly.
4	
5	const SR = 44100;
6	
7	function buffer(seconds) {
8	  return new Float32Array(Math.floor(SR * seconds));
9	}
10	
11	// Cheap deterministic noise
12	function makeNoise(seed) {
13	  let s = seed >>> 0;
14	  return () => {
15	    s = (s * 1664525 + 1013904223) >>> 0;
16	    return (s / 4294967296) * 2 - 1;
17	  };
18	}
19	
20	// One-pole lowpass over an existing buffer, in place
21	function lowpass(buf, cutoffHz) {
22	  const a = 1 - Math.exp(-2 * Math.PI * cutoffHz / SR);
23	  let y = 0;
24	  for (let i = 0; i < buf.length; i++) {
25	    y += a * (buf[i] - y);
26	    buf[i] = y;
27	  }
28	  return buf;
29	}
30	
31	function highpass(buf, cutoffHz) {
32	  const a = 1 - Math.exp(-2 * Math.PI * cutoffHz / SR);
33	  let lp = 0;
34	  for (let i = 0; i < buf.length; i++) {
35	    lp += a * (buf[i] - lp);
36	    buf[i] = buf[i] - lp;
37	  }
38	  return buf;
39	}
40	
41	function expEnv(buf, decay) {
42	  for (let i = 0; i < buf.length; i++) buf[i] *= Math.exp(-i / SR * decay);
43	  return buf;
44	}
45	
46	function addSine(buf, freqStart, freqEnd, amp, decay, offset = 0) {
47	  let phase = 0;
48	  const n = buf.length;
49	  const off = Math.floor(offset * SR);
50	  for (let i = off; i < n; i++) {
51	    const t = (i - off) / SR;
52	    const k = (i - off) / (n - off);
53	    const f = freqStart + (freqEnd - freqStart) * k;
54	    phase += 2 * Math.PI * f / SR;
55	    buf[i] += Math.sin(phase) * amp * Math.exp(-t * decay);
56	  }
57	  return buf;
58	}
59	
60	function addNoiseBurst(buf, amp, decay, seed, offset = 0, len = 1) {
61	  const rnd = makeNoise(seed);
62	  const off = Math.floor(offset * SR);
63	  const end = Math.min(buf.length, off + Math.floor(len * SR));
64	  for (let i = off; i < end; i++) {
65	    const t = (i - off) / SR;
66	    buf[i] += rnd() * amp * Math.exp(-t * decay);
67	  }
68	  return buf;
69	}
70	
71	function addClick(buf, amp, offset, seed) {
72	  const rnd = makeNoise(seed);
73	  const off = Math.floor(offset * SR);
74	  const len = Math.floor(0.012 * SR);
75	  for (let i = 0; i < len && off + i < buf.length; i++) {
76	    buf[off + i] += rnd() * amp * Math.exp(-i / SR * 600);
77	  }
78	  return buf;
79	}
80	
81	function normalize(buf, target = 0.85) {
82	  let peak = 0;
83	  for (let i = 0; i < buf.length; i++) peak = Math.max(peak, Math.abs(buf[i]));
84	  if (peak > 0) {
85	    const g = target / peak;
86	    for (let i = 0; i < buf.length; i++) buf[i] *= g;
87	  }
88	  return buf;
89	}
