259	function genAmbient() {
260	  const b = buffer(4.0);
261	  const rnd = makeNoise(31337);
262	  // wind bed
263	  for (let i = 0; i < b.length; i++) b[i] = rnd() * 0.5;
264	  lowpass(b, 220);
265	  // slow amplitude wobble + hum
266	  for (let i = 0; i < b.length; i++) {
267	    const t = i / SR;
268	    b[i] *= 0.5 + 0.5 * Math.sin(2 * Math.PI * 0.21 * t);
269	    b[i] += 0.08 * Math.sin(2 * Math.PI * 55 * t) * (0.7 + 0.3 * Math.sin(2 * Math.PI * 0.13 * t));
270	  }
271	  // crossfade loop seam
272	  const fade = Math.floor(0.25 * SR);
273	  for (let i = 0; i < fade; i++) {
274	    const k = i / fade;
275	    b[i] = b[i] * k + b[b.length - fade + i] * (1 - k);
276	  }
277	  return normalize(b, 0.3);
278	}
