304	export class AudioEngine {
305	  constructor(settings) {
306	    this.settings = settings;
307	    this.ctx = null;
308	    this.buffers = {};
309	    this.raw = {};
310	    this.ambientNode = null;
311	    for (const [name, gen] of Object.entries(SFX_GENERATORS)) {
312	      this.raw[name] = gen();
313	    }
314	  }
315	
316	  // Must be called from a user gesture
317	  unlock() {
318	    if (this.ctx) {
319	      if (this.ctx.state === 'suspended') this.ctx.resume();
320	      return;
321	    }
322	    const AC = window.AudioContext || window.webkitAudioContext;
323	    if (!AC) return;
324	    this.ctx = new AC();
325	    this.master = this.ctx.createGain();
326	    this.master.connect(this.ctx.destination);
327	    for (const [name, data] of Object.entries(this.raw)) {
328	      const buf = this.ctx.createBuffer(1, data.length, SR);
329	      buf.getChannelData(0).set(data);
330	      this.buffers[name] = buf;
331	    }
332	    this._applyVolumes();
333	  }
334	
335	  _applyVolumes() {
336	    if (this.master) this.master.gain.value = this.settings.get('audio.master') / 100;
337	  }
338	
339	  // pan: -1..1, dist: world units (0 = full volume)
340	  play(name, { pan = 0, dist = 0, vol = 1, category = 'sfx' } = {}) {
341	    if (!this.ctx || this.ctx.state !== 'running') return;
342	    const buf = this.buffers[name];
343	    if (!buf) return;
344	    this._applyVolumes();
345	    const src = this.ctx.createBufferSource();
346	    src.buffer = buf;
347	    const gain = this.ctx.createGain();
348	    const catVol = this.settings.get(`audio.${category}`) / 100;
349	    const att = dist > 0 ? Math.min(1, 9 / (dist + 3)) : 1;
350	    gain.gain.value = vol * catVol * att;
351	    src.connect(gain);
352	    if (this.ctx.createStereoPanner) {
353	      const p = this.ctx.createStereoPanner();
354	      p.pan.value = Math.max(-1, Math.min(1, pan));
355	      gain.connect(p);
356	      p.connect(this.master);
357	    } else {
358	      gain.connect(this.master);
359	    }
360	    src.start();
361	  }
362	
363	  startAmbient() {
364	    if (!this.ctx || this.ambientNode) return;
365	    const src = this.ctx.createBufferSource();
366	    src.buffer = this.buffers.ambient;
367	    src.loop = true;
368	    const gain = this.ctx.createGain();
369	    gain.gain.value = this.settings.get('audio.ambient') / 100;
370	    src.connect(gain);
371	    gain.connect(this.master);
372	    src.start();
373	    this.ambientNode = { src, gain };
374	  }
375	
376	  updateAmbient() {
377	    if (this.ambientNode) {
378	      this.ambientNode.gain.gain.value = this.settings.get('audio.ambient') / 100;
379	    }
380	    this._applyVolumes();
381	  }
382	
383	  // Test hook: report stats on every generated sound
384	  report() {
385	    const out = {};
386	    for (const [name, data] of Object.entries(this.raw)) {
387	      let peak = 0, sum = 0;
388	      for (let i = 0; i < data.length; i++) {
389	        const v = Math.abs(data[i]);
390	        if (v > peak) peak = v;
391	        sum += data[i] * data[i];
392	      }
393	      out[name] = {
394	        seconds: +(data.length / SR).toFixed(3),
395	        peak: +peak.toFixed(4),
396	        rms: +Math.sqrt(sum / data.length).toFixed(4),
397	      };
398	    }
399	    return out;
400	  }
401	}
